  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children[pid].append(n['id'])
    all_descendants = {}
    def dfs(node_id):
        desc = [node_id]
        for cid in children.get(node_id, []):
            desc.extend(dfs(cid))
        all_descendants[node_id] = desc
        return desc
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            dfs(root_id)
            break
    retained = set(node_by_id.keys())
    from collections import Counter
    total_symbols = Counter()
    for n in nodes:
        total_symbols[n['symbol']] += 1
    order = sorted(nodes, key=lambda x: (-x['depth'], x['id']))
    removed = []
    for node in order:
        node_id = node['id']
        if not node['removable']:
            continue
        if node_id not in retained:
            continue
        # determine retained descendants of this node (including itself)
        descendant_ids = all_descendants[node_id]
        retained_desc = [did for did in descendant_ids if did in retained]
        # if any descendant other than self is still retained, skip
        if len(retained_desc) > 1:
            continue
        # compute current symbol counts for the retained part of this subtree
        sub_counts = Counter()
        for did in retained_desc:
            sub_counts[node_by_id[did]['symbol']] += 1
        # check required symbols after removal
        feasible = True
        for req in required_symbols:
            if total_symbols[req] - sub_counts.get(req, 0) < 1:
                feasible = False
                break
        if not feasible:
            continue
        # remove node (its retained part is just itself at this point)
        retained.remove(node_id)
        for sym, cnt in sub_counts.items():
            total_symbols[sym] -= cnt
        removed.append(node_id)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"
}
